"""Reporting queries for the harbour stays database."""


def owners_without_vessels(conn):
    """Owners without vessels."""
    return conn.execute(
        """
    SELECT p.name
    FROM owner p
    WHERE p.id NOT IN (SELECT parent_id FROM vessel)
    ORDER BY p.name
        """
    ).fetchall()


def running_fee(conn):
    """Running fee."""
    return conn.execute(
        """
    SELECT day, fee, running FROM (
      SELECT e.day AS day, e.fee AS fee, e.id AS id,
             SUM(e.fee) OVER (ORDER BY e.day, e.id) AS running
      FROM stay e
    )
    ORDER BY day DESC, id DESC
    LIMIT 2
        """
    ).fetchall()


def smallest_vessels(conn):
    """Smallest vessels."""
    return conn.execute(
        """
    SELECT label, length_m
    FROM vessel
    ORDER BY length_m, id
    LIMIT 2
        """
    ).fetchall()


def unflagged_stays(conn):
    """Unflagged stays."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM stay WHERE paid != 1
        """
    ).fetchall()


def kind_counts(conn):
    """Kind counts."""
    return conn.execute(
        """
    SELECT kind, COUNT(*) AS n
    FROM vessel
    GROUP BY kind
    HAVING COUNT(*) >= 2
    ORDER BY n DESC, kind
        """
    ).fetchall()

start.app/schema.sql:
CREATE TABLE owner (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  country TEXT
);

CREATE TABLE vessel (
  id INTEGER PRIMARY KEY,
  parent_id INTEGER REFERENCES owner(id),
  label TEXT NOT NULL,
  kind TEXT NOT NULL,
  length_m INTEGER
);

CREATE TABLE stay (
  id INTEGER PRIMARY KEY,
  child_id INTEGER NOT NULL REFERENCES vessel(id),
  day TEXT NOT NULL,
  fee INTEGER NOT NULL,
  paid INTEGER,
  note TEXT
);

