"""Reporting queries for the seed library database."""


def donor_region_totals(conn):
    """Donor region totals."""
    return conn.execute(
        """
    WITH per_parent AS (
      SELECT p.id AS pid, p.region AS grp, COUNT(DISTINCT c.id) AS kids, COALESCE(SUM(e.days_out), 0) AS total
      FROM donor p
      LEFT JOIN packet c ON c.parent_id = p.id
      LEFT JOIN loan e ON e.child_id = c.id
      GROUP BY p.id
    )
    SELECT COALESCE(grp, '(none)') AS grp, SUM(kids) AS kids, SUM(total) AS total
    FROM per_parent
    GROUP BY grp
    ORDER BY total DESC, grp
        """
    ).fetchall()


def packets_starting_k(conn):
    """Packets starting k."""
    return conn.execute(
        """
    SELECT label
    FROM packet
    WHERE label LIKE 'k%'
    ORDER BY label
        """
    ).fetchall()


def distinct_labels(conn):
    """Distinct labels."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM (
      SELECT species AS v FROM packet
      UNION
      SELECT region FROM donor
    )
        """
    ).fetchall()


def unflagged_loans(conn):
    """Unflagged loans."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM loan WHERE returned != 1
        """
    ).fetchall()


def packet_pairs(conn):
    """Packet pairs."""
    return conn.execute(
        """
    SELECT a.label, b.label
    FROM packet a
    JOIN packet b ON a.parent_id = b.parent_id AND a.id < b.id
    ORDER BY a.id, b.id
        """
    ).fetchall()

