CREATE TABLE donor (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  region TEXT
);

CREATE TABLE packet (
  id INTEGER PRIMARY KEY,
  parent_id INTEGER REFERENCES donor(id),
  label TEXT NOT NULL,
  species TEXT NOT NULL,
  qty INTEGER
);

CREATE TABLE loan (
  id INTEGER PRIMARY KEY,
  child_id INTEGER NOT NULL REFERENCES packet(id),
  day TEXT NOT NULL,
  days_out INTEGER NOT NULL,
  returned INTEGER,
  note TEXT
);

