"""Reporting queries for the observing log database."""


def scope_schmidt_share(conn):
    """Scope schmidt share."""
    return conn.execute(
        """
    SELECT COUNT(*) AS n, SUM(CASE WHEN scope = 'schmidt' THEN 1 ELSE 0 END) AS hits, COUNT(hours) AS sized
    FROM session
        """
    ).fetchall()


def unflagged_shots(conn):
    """Unflagged shots."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM shot WHERE kept != 1
        """
    ).fetchall()


def session_pairs(conn):
    """Session pairs."""
    return conn.execute(
        """
    SELECT a.label, b.label
    FROM session a
    JOIN session b ON a.parent_id = b.parent_id AND a.id < b.id
    ORDER BY a.id, b.id
        """
    ).fetchall()


def mean_frames_per_observer(conn):
    """Mean frames per observer."""
    return conn.execute(
        """
    SELECT p.name, SUM(e.frames) / COUNT(*) AS mean
    FROM observer p
    JOIN session c ON c.parent_id = p.id
    JOIN shot e ON e.child_id = c.id
    GROUP BY p.id
    ORDER BY mean DESC, p.name
        """
    ).fetchall()


def smallest_sessions(conn):
    """Smallest sessions."""
    return conn.execute(
        """
    SELECT label, hours
    FROM session
    ORDER BY hours, id
    LIMIT 4
        """
    ).fetchall()

