"""Reporting queries for the bell deliveries database."""


def mean_fee_per_foundry(conn):
    """Mean fee per foundry."""
    return conn.execute(
        """
    SELECT p.name, SUM(e.fee) / COUNT(*) AS mean
    FROM foundry p
    JOIN bell c ON c.parent_id = p.id
    JOIN delivery e ON e.child_id = c.id
    GROUP BY p.id
    ORDER BY mean DESC, p.name
        """
    ).fetchall()


def foundrys_with_flagged_deliverys(conn):
    """Foundrys with flagged deliverys."""
    return conn.execute(
        """
    SELECT COUNT(DISTINCT p.id)
    FROM foundry p
    JOIN bell c ON c.parent_id = p.id
    JOIN delivery e ON e.child_id = c.id
    WHERE e.fragile = 1
        """
    ).fetchall()


def unflagged_deliverys(conn):
    """Unflagged deliverys."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM delivery WHERE fragile != 1
        """
    ).fetchall()


def running_fee(conn):
    """Running fee."""
    return conn.execute(
        """
    SELECT day, fee, running FROM (
      SELECT e.day AS day, e.fee AS fee, e.id AS id,
             SUM(e.fee) OVER (ORDER BY e.day, e.id) AS running
      FROM delivery e
    )
    ORDER BY day DESC, id DESC
    LIMIT 3
        """
    ).fetchall()


def top_fee_ranked(conn):
    """Top fee ranked."""
    return conn.execute(
        """
    SELECT label, fee, rk FROM (
      SELECT c.label AS label, e.fee AS fee, RANK() OVER (ORDER BY e.fee DESC) AS rk, e.id AS eid
      FROM delivery e JOIN bell c ON c.id = e.child_id
    )
    WHERE rk <= 4
    ORDER BY rk, eid
        """
    ).fetchall()

