"""Reporting queries for the hive inspections database."""


def hives_starting_h(conn):
    """Hives starting h."""
    return conn.execute(
        """
    SELECT label
    FROM hive
    WHERE label LIKE 'h%'
    ORDER BY label
        """
    ).fetchall()


def hives_per_apiary(conn):
    """Hives per apiary."""
    return conn.execute(
        """
    SELECT p.name, COUNT(c.id) AS n
    FROM apiary p
    LEFT JOIN hive c ON c.parent_id = p.id
    GROUP BY p.id
    ORDER BY n, p.name
        """
    ).fetchall()


def top_honey_g_ranked(conn):
    """Top honey g ranked."""
    return conn.execute(
        """
    SELECT label, honey_g, rk FROM (
      SELECT c.label AS label, e.honey_g AS honey_g, RANK() OVER (ORDER BY e.honey_g DESC) AS rk, e.id AS eid
      FROM inspection e JOIN hive c ON c.id = e.child_id
    )
    WHERE rk <= 3
    ORDER BY rk, eid
        """
    ).fetchall()


def hive_pairs(conn):
    """Hive pairs."""
    return conn.execute(
        """
    SELECT a.label, b.label
    FROM hive a
    JOIN hive b ON a.parent_id = b.parent_id AND a.id < b.id
    ORDER BY a.id, b.id
        """
    ).fetchall()


def breed_caucasian_share(conn):
    """Breed caucasian share."""
    return conn.execute(
        """
    SELECT COUNT(*) AS n, SUM(CASE WHEN breed = 'caucasian' THEN 1 ELSE 0 END) AS hits, COUNT(frames) AS sized
    FROM hive
        """
    ).fetchall()

