"""Reporting queries for the bell deliveries database."""


def top_fee_ranked(conn):
    """Top fee ranked."""
    return conn.execute(
        """
    SELECT label, fee, rk FROM (
      SELECT c.label AS label, e.fee AS fee, RANK() OVER (ORDER BY e.fee DESC) AS rk, e.id AS eid
      FROM delivery e JOIN bell c ON c.id = e.child_id
    )
    WHERE rk <= 5
    ORDER BY rk, eid
        """
    ).fetchall()


def unflagged_deliverys(conn):
    """Unflagged deliverys."""
    return conn.execute(
        """
    SELECT COUNT(*) FROM delivery WHERE fragile != 1
        """
    ).fetchall()


def bells_per_foundry(conn):
    """Bells per foundry."""
    return conn.execute(
        """
    SELECT p.name, COUNT(c.id) AS n
    FROM foundry p
    LEFT JOIN bell c ON c.parent_id = p.id
    GROUP BY p.id
    ORDER BY n, p.name
        """
    ).fetchall()


def bell_activity_span(conn):
    """Bell activity span."""
    return conn.execute(
        """
    SELECT c.label, CAST(julianday(MAX(e.day)) - julianday(MIN(e.day)) AS INTEGER) AS span
    FROM bell c JOIN delivery e ON e.child_id = c.id
    GROUP BY c.id
    HAVING span >= 8
    ORDER BY span DESC, c.label
        """
    ).fetchall()


def foundrys_without_bells(conn):
    """Foundrys without bells."""
    return conn.execute(
        """
    SELECT p.name
    FROM foundry p
    WHERE p.id NOT IN (SELECT parent_id FROM bell)
    ORDER BY p.name
        """
    ).fetchall()

